import{_ as e,o as i,c as r,a as l}from"./app.DLiRGumz.js";const b=JSON.parse('{"title":"Domain Playbooks for Delegation","description":"","frontmatter":{},"headers":[],"relativePath":"governance/DOMAIN_PLAYBOOKS.md","filePath":"governance/DOMAIN_PLAYBOOKS.md","lastUpdated":1771823011000}'),o={name:"governance/DOMAIN_PLAYBOOKS.md"};function n(t,a,s,d,c,h){return i(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="domain-playbooks-for-delegation" tabindex="-1">Domain Playbooks for Delegation <a class="header-anchor" href="#domain-playbooks-for-delegation" aria-label="Permalink to &quot;Domain Playbooks for Delegation&quot;">​</a></h1><h2 id="global-defaults" tabindex="-1">Global Defaults <a class="header-anchor" href="#global-defaults" aria-label="Permalink to &quot;Global Defaults&quot;">​</a></h2><ol><li>Every task starts with classifier pass.</li><li>Every worker has explicit ownership boundaries.</li><li>Every lane requires independent verification.</li></ol><h2 id="backend" tabindex="-1">Backend <a class="header-anchor" href="#backend" aria-label="Permalink to &quot;Backend&quot;">​</a></h2><ol><li>Delegate API/schema changes to backend specialist + test worker.</li><li>Require unit and integration gates by default.</li></ol><h2 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h2><ol><li>Delegate UI logic and interaction tests separately.</li><li>Require lint, type-check, and accessibility gates.</li></ol><h2 id="infra-and-ci-cd" tabindex="-1">Infra and CI/CD <a class="header-anchor" href="#infra-and-ci-cd" aria-label="Permalink to &quot;Infra and CI/CD&quot;">​</a></h2><ol><li>Separate pipeline logic from app logic workers.</li><li>Require dry-run plus local parity checks before promotion.</li></ol><h2 id="data-and-migrations" tabindex="-1">Data and Migrations <a class="header-anchor" href="#data-and-migrations" aria-label="Permalink to &quot;Data and Migrations&quot;">​</a></h2><ol><li>Isolate migration tasks in dedicated lane or burst worktree.</li><li>Require backward/forward integrity checks and rollback plan.</li></ol><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><ol><li>Use dedicated security specialist lane.</li><li>Require threat-model delta and security regression checks.</li></ol><h2 id="qa-and-reliability" tabindex="-1">QA and Reliability <a class="header-anchor" href="#qa-and-reliability" aria-label="Permalink to &quot;QA and Reliability&quot;">​</a></h2><ol><li>Assign independent verification worker(s).</li><li>Cover integration, e2e, and reliability probes.</li></ol><h2 id="docs-and-governance" tabindex="-1">Docs and Governance <a class="header-anchor" href="#docs-and-governance" aria-label="Permalink to &quot;Docs and Governance&quot;">​</a></h2><ol><li>Update governance docs in the same change wave as policy changes.</li><li>Ensure docs reference executable checks and enforcement points.</li></ol><h2 id="research" tabindex="-1">Research <a class="header-anchor" href="#research" aria-label="Permalink to &quot;Research&quot;">​</a></h2><ol><li>Split source gathering and synthesis roles.</li><li>Prefer primary specifications and official documentation.</li></ol><h2 id="release-and-operations" tabindex="-1">Release and Operations <a class="header-anchor" href="#release-and-operations" aria-label="Permalink to &quot;Release and Operations&quot;">​</a></h2><ol><li>Use integration worktree and merge train.</li><li>Gate on smoke tests, rollback readiness, and change audit completeness.</li></ol>',21)])])}const f=e(o,[["render",n]]);export{b as __pageData,f as default};
